import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const surfaceWidth = 3.35;
  const surfaceHeight = 2.1;
  const atlasWidth = 512;
  const atlasHeight = 320;
  const sourceRect = {
    x: 0,
    y: 0,
    width: 512,
    height: 320
  };

  const surfaceGeometry = new PlaneGeometry(surfaceWidth, surfaceHeight);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  surfaceMaterial.colorNode = mix(
    vec3('#0b0b10'),
    vec3('#16161d'),
    gradientT
  );

  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.z = -0.035;
  root.add(surface);
  resources.push(surfaceGeometry, surfaceMaterial);

  const accentGeometry = new PlaneGeometry(0.055, 1.28);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: false
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-surfaceWidth * 0.5 + 0.18, 0, 0.015);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const imageGeometry = new PlaneGeometry(surfaceWidth, surfaceHeight);
  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.z = 0.025;
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const billboard = (_, __, camera) => {
    if (!disposed && camera) {
      root.quaternion.copy(camera.quaternion);
    }
  };

  surface.onBeforeRender = billboard;
  accent.onBeforeRender = billboard;
  imagePlane.onBeforeRender = billboard;

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed || !texture) return;

      const image = texture.image;
      const width = image?.width || atlasWidth;
      const height = image?.height || atlasHeight;

      texture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      texture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        sourceRect.width / width,
        sourceRect.height / height
      );
      texture.offset.set(
        sourceRect.x / width,
        1 - ((sourceRect.y + sourceRect.height) / height)
      );

      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    surface.onBeforeRender = null;
    accent.onBeforeRender = null;
    imagePlane.onBeforeRender = null;

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }
  };

  root.scale.setScalar(0.96);
  const entrance = gsap.timeline({
    defaults: {
      overwrite: true
    }
  });

  entrance
    .to(root.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.42,
      ease: 'power3.out'
    })
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.48,
      ease: 'power4.out'
    });

  timelines.push(entrance);

  return root;
}
